package com.corp.hr.controller;

import com.corp.hr.entity.Department;
import com.corp.hr.repository.DepartmentRepository;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/hr/departments")
public class DepartmentController {

    private final DepartmentRepository departmentRepository;

    public DepartmentController(DepartmentRepository departmentRepository) {
        this.departmentRepository = departmentRepository;
    }

    @GetMapping("/{deptId}")
    public ResponseEntity<Department> getDepartmentStructure(@PathVariable String deptId) {
        // Traverses lazy-loaded disciplinaryRecords during serialization
        Department dept = departmentRepository.findByCode(deptId)
                .orElseThrow(() -> new IllegalArgumentException("Department not found"));
        return ResponseEntity.ok(dept);
    }
}

